//! Typed identifiers.
//!
//! Every ID is a `UUIDv7` (`docs/plan.md` §1), generated by the client for master data
//! (spec 2.1 §8, idempotent `PUT /resource/{uuid}`). Each entity has its own newtype so that
//! a [`UserId`] can never be passed where a [`RoleId`] is expected.

use std::fmt;
use std::str::FromStr;

use uuid::Uuid;

macro_rules! id_type {
    ($(#[$meta:meta])* $name:ident) => {
        $(#[$meta])*
        #[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
        pub struct $name(Uuid);

        impl $name {
            /// Generates a new time-ordered `UUIDv7` identifier.
            #[must_use]
            pub fn generate() -> Self {
                Self(Uuid::now_v7())
            }

            /// Wraps an existing UUID. `const`, so well-known IDs (e.g. the seeded roles) can be
            /// constants.
            #[must_use]
            pub const fn from_uuid(uuid: Uuid) -> Self {
                Self(uuid)
            }

            /// Returns the underlying UUID.
            #[must_use]
            pub const fn as_uuid(&self) -> &Uuid {
                &self.0
            }
        }

        impl From<Uuid> for $name {
            fn from(uuid: Uuid) -> Self {
                Self(uuid)
            }
        }

        impl From<$name> for Uuid {
            fn from(id: $name) -> Self {
                id.0
            }
        }

        impl fmt::Display for $name {
            fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
                self.0.fmt(f)
            }
        }

        impl FromStr for $name {
            type Err = uuid::Error;

            fn from_str(s: &str) -> Result<Self, Self::Err> {
                Uuid::parse_str(s).map(Self)
            }
        }
    };
}

id_type!(
    /// The company (exactly one per install for now, spec 2.1 §1).
    CompanyId
);
id_type!(
    /// A branch (store), spec 2.1 §1.
    BranchId
);
id_type!(
    /// A register (till), a machine identity of its own, spec 2.1 §2.
    RegisterId
);
id_type!(
    /// A stock location within a branch, spec 2.1 §1.
    LocationId
);
id_type!(
    /// A user (cashier, manager, back-office staff), spec 2.1 §3–4.
    UserId
);
id_type!(
    /// A role: a named set of permission grants, spec 2.1 §3.
    RoleId
);
id_type!(
    /// A cashier session: whose money is in the drawer, spec 2.1 §5.
    CashierSessionId
);
id_type!(
    /// A catalog product, spec 2.2 §2.
    ProductId
);
id_type!(
    /// A product variant (the thing that is sold and stocked), spec 2.2 §3.
    VariantId
);
id_type!(
    /// A unit of measure of one product, spec 2.2 §4.
    UnitId
);
id_type!(
    /// An option attribute of a product (e.g. Size), spec 2.2 §3.
    OptionId
);
id_type!(
    /// One value of an option (e.g. Medium), spec 2.2 §3.
    OptionValueId
);
id_type!(
    /// A barcode on a variant + unit, spec 2.2 §6.
    BarcodeId
);
id_type!(
    /// A node of the category tree, spec 2.2 §8.
    CategoryId
);
id_type!(
    /// A brand, spec 2.2 §8.
    BrandId
);
id_type!(
    /// A tax class of products (`Standard`, `Exempt`; rates in spec 2.3), spec 2.2 §2.
    TaxClassId
);

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn generated_ids_are_v7_and_ordered() {
        let a = UserId::generate();
        let b = UserId::generate();
        assert_eq!(a.as_uuid().get_version_num(), 7);
        assert_ne!(a, b);
        assert!(a < b, "UUIDv7 is time-ordered");
    }

    #[test]
    fn string_and_uuid_round_trip() {
        let id = BranchId::generate();
        let parsed: BranchId = id.to_string().parse().unwrap();
        assert_eq!(parsed, id);

        let uuid: Uuid = id.into();
        assert_eq!(BranchId::from(uuid), id);
    }

    #[test]
    fn const_from_uuid_wraps_the_uuid() {
        const ID: RoleId = RoleId::from_uuid(Uuid::from_u128(1));
        assert_eq!(*ID.as_uuid(), Uuid::from_u128(1));
        assert_eq!(ID, RoleId::from(Uuid::from_u128(1)));
    }

    #[test]
    fn invalid_string_is_rejected() {
        assert!("not-a-uuid".parse::<RoleId>().is_err());
    }
}
